16	  String build(String function, [List<String> pathParams = const []]) {
17	    final trimmedBase =
18	        baseUrl.endsWith('/') ? baseUrl.substring(0, baseUrl.length - 1) : baseUrl;
19	    final segments = [function, ...pathParams];
20	    return '$trimmedBase/${segments.join('/')}';
