      stubMalformedResponse();
      final result = await invoke();
      expect(result.isLeft(), isTrue);
    });

    test('no connection -> Left(Failure), no unhandled exception', () async {
      stubNoConnection();
      final result = await invoke();
      expect(result.isLeft(), isTrue);
    });
  });
}

